import sys,json
for line in sys.stdin:
    try: o=json.loads(line)
    except: continue
    t=o.get("type")
    if t=="assistant":
        for b in o.get("message",{}).get("content",[]):
            if b.get("type")=="text" and b.get("text","").strip():
                print("[TEXT]", b["text"][:400])
            elif b.get("type")=="tool_use":
                inp=b.get("input",{})
                cmd=inp.get("command") or inp.get("file_path") or str(inp)[:200]
                print("[TOOL]", b.get("name"), "->", str(cmd)[:200])
    elif t=="result":
        print("[RESULT]", str(o.get("subtype")), str(o.get("num_turns")))
' 2>/dev/null | tail -40
